// NULL-tolerant scan buffer for ledgerEntryScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type ledgerEntryPreloadBuf struct {
	ID               sql.Null[uuid.UUID]
	HouseholdID      sql.Null[uuid.UUID]
	JournalID        sql.Null[uuid.UUID]
	Kind             sql.Null[string]
	OccurredAt       sql.Null[time.Time]
	Description      sql.Null[string]
	AmountYen        sql.Null[int64]
	FromMemberID     sql.Null[uuid.UUID]
	ToMemberID       sql.Null[uuid.UUID]
	PoolID           sql.Null[uuid.UUID]
	SourcePurchaseID sql.Null[uuid.UUID]
	CreatedAt        sql.Null[time.Time]
}

// ledgerEntryScanMapperNullable maps the preloaded ledgerEntry
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func ledgerEntryScanMapperNullable(prefix string) scan.Mapper[*LedgerEntry] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*LedgerEntry, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *ledgerEntryPreloadBuf) any
		}
		targets := make([]target, 0, 12)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.HouseholdID }})
			case "journal_id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.JournalID }})
			case "kind":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.Kind }})
			case "occurred_at":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.OccurredAt }})
			case "description":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.Description }})
			case "amount_yen":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.AmountYen }})
			case "from_member_id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.FromMemberID }})
			case "to_member_id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.ToMemberID }})
			case "pool_id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.PoolID }})
			case "source_purchase_id":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.SourcePurchaseID }})
			case "created_at":
				targets = append(targets, target{i, func(b *ledgerEntryPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(ledgerEntryPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*LedgerEntry, error) {
				buf := link.(*ledgerEntryPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.JournalID.Valid) &&
					!(buf.Kind.Valid) &&
					!(buf.OccurredAt.Valid) &&
					!(buf.Description.Valid) &&
					!(buf.AmountYen.Valid) &&
					!(buf.FromMemberID.Valid) &&
					!(buf.ToMemberID.Valid) &&
					!(buf.PoolID.Valid) &&
					!(buf.SourcePurchaseID.Valid) &&
					!(buf.CreatedAt.Valid) {
					return nil, nil
				}

				o := new(LedgerEntry)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.JournalID.Valid {
					o.JournalID = buf.JournalID.V
				}
				if buf.Kind.Valid {
					o.Kind = buf.Kind.V
				}
				if buf.OccurredAt.Valid {
					o.OccurredAt = buf.OccurredAt.V
				}
				if buf.Description.Valid {
					o.Description = buf.Description.V
				}
				if buf.AmountYen.Valid {
					o.AmountYen = buf.AmountYen.V
				}
				o.FromMemberID = buf.FromMemberID
				o.ToMemberID = buf.ToMemberID
				o.PoolID = buf.PoolID
				o.SourcePurchaseID = buf.SourcePurchaseID
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				return o, nil
			}
	}
}

