// LoadFromMemberMember loads the ledgerEntry's FromMemberMember into the .R struct
func (o *LedgerEntry) LoadFromMemberMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.FromMemberMember = nil
	o.R.Loaded.FromMemberMember = false

	related, err := o.FromMemberMember(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.FromMemberLedgerEntries = LedgerEntrySlice{o}

	o.R.FromMemberMember = related
	o.R.Loaded.FromMemberMember = true
	return nil
}

// LoadFromMemberMember loads the ledgerEntry's FromMemberMember into the .R struct
func (os LedgerEntrySlice) LoadFromMemberMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.FromMemberMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.FromMemberMember = nil
		o.R.Loaded.FromMemberMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	ledgerEntryByKey := make(map[uuid.UUID][]*LedgerEntry, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.FromMemberID.Valid {
			continue
		}

		ledgerEntryByKey[o.FromMemberID.V] = append(ledgerEntryByKey[o.FromMemberID.V], o)
	}

	for _, rel := range members {

		owners, ok := ledgerEntryByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.FromMemberMember != nil {
				continue
			}

			rel.R.FromMemberLedgerEntries = append(rel.R.FromMemberLedgerEntries, o)

			o.R.FromMemberMember = rel

		}
	}

	return nil
}

