type ledgerEntryJoins[Q dialect.Joinable] struct {
	typ              string
	FromMemberMember modAs[Q, memberColumns]
	Household        modAs[Q, householdColumns]
	Pool             modAs[Q, poolColumns]
	Purchase         modAs[Q, purchaseColumns]
	Journal          modAs[Q, journalColumns]
	ToMemberMember   modAs[Q, memberColumns]
	Transfer         modAs[Q, transferColumns]
}

func (j ledgerEntryJoins[Q]) aliasedAs(alias string) ledgerEntryJoins[Q] {
	return buildLedgerEntryJoins[Q](buildLedgerEntryColumns(alias), j.typ)
}

func buildLedgerEntryJoins[Q dialect.Joinable](cols ledgerEntryColumns, typ string) ledgerEntryJoins[Q] {
	return ledgerEntryJoins[Q]{
		typ: typ,
		FromMemberMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.FromMemberID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Pool: modAs[Q, poolColumns]{
			c: Pools.Columns,
			f: func(to poolColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Pools.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PoolID),
					))
				}

				return mods
			},
		},
		Purchase: modAs[Q, purchaseColumns]{
			c: Purchases.Columns,
			f: func(to purchaseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Purchases.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.SourcePurchaseID),
					))
				}

				return mods
			},
		},
		Journal: modAs[Q, journalColumns]{
			c: Journals.Columns,
			f: func(to journalColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Journals.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.JournalID),
					))
				}

				return mods
			},
		},
		ToMemberMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ToMemberID),
					))
				}

				return mods
			},
		},
		Transfer: modAs[Q, transferColumns]{
			c: Transfers.Columns,
			f: func(to transferColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Transfers.NameExpr().As(to.Alias())).On(
						to.LedgerEntryID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
